package main

import (
	"log"
	"net/http"
	"runtime/pprof"
	"time"
)

func capture(w http.ResponseWriter, r *http.Request) {
	pprof.StartCPUProfile(w)
	time.Sleep(30 * time.Second)
	pprof.StopCPUProfile()
}

func main() {
	http.HandleFunc("/cpu", capture)
	log.Fatal(http.ListenAndServe("127.0.0.1:6060", nil))
}
